import importlib.util, io, stat
from pathlib import Path
from types import SimpleNamespace
from unittest.mock import patch
from zipfile import ZipFile, ZipInfo
path=Path('records/aws_prefix_diagnostic_v8_001/analyze_results.py')
spec=importlib.util.spec_from_file_location('prefix_analysis_check',path)
a=importlib.util.module_from_spec(spec); spec.loader.exec_module(a)
checks=0
def zipped(entries):
    out=io.BytesIO()
    with ZipFile(out,'w') as z:
        for name,value in entries: z.writestr(name,value)
    return out.getvalue()
def packet(raw):
    info=SimpleNamespace(st_mode=stat.S_IFREG,st_size=len(raw),st_dev=1,st_ino=2,st_mtime_ns=3)
    return SimpleNamespace(stat=lambda:info,open=lambda mode:io.BytesIO(raw))
for entries,reason in [([('../escape',b'x')],'UNSAFE_ZIP_PATH'),([('A',b'x'),('a',b'y')],'ZIP_DUPLICATE_OR_MEMBER_BOUND')]:
    with patch.object(a,'no_links',return_value=packet(zipped(entries))):
        try: a.read_packet('memory')
        except ValueError as exc: assert reason in str(exc)
        else: raise AssertionError(reason)
    checks+=1
link=ZipInfo('link'); link.create_system=3; link.external_attr=(stat.S_IFLNK|0o777)<<16
with patch.object(a,'no_links',return_value=packet(zipped([(link,b'target')]))):
    try: a.read_packet('memory')
    except ValueError as exc: assert 'ZIP_LINK_DIRECTORY_ENCRYPTION_OR_FILE_BOUND' in str(exc)
    else: raise AssertionError('link accepted')
checks+=1
receipt={'schema':'cas-meta2-assisted-prefix-diagnostic/8','source_sha':a.WORKER_SHA,'bundle_manifest_sha256':a.BUNDLE_SHA,'neural_training':False,'native_execution':False,'completed':False,'files_sha256':{'cas_initial_train_probe_000.json':'0'*64}}
members={'diagnostic/diagnostic_receipt.json':a.canonical(receipt),'diagnostic/cas_initial_train_probe_000.json':b'NOT VALID JSON'}
with patch.object(a,'read_packet',return_value=(members,{})):
    try: a.analyze('memory')
    except ValueError as exc: assert 'DIAGNOSTIC_ROW_HASH_MISMATCH' in str(exc),str(exc)
    else: raise AssertionError('invalid row parsed before hash')
checks+=1
with patch.object(a,'read_packet',return_value=({'diagnostic/diagnostic_receipt.json':a.canonical(receipt)},{})):
    result=a.analyze('memory')
    assert result['status']=='INCOMPLETE_PACKET_DIAGNOSTIC_INDEX_NOT_FULLY_VERIFIABLE' and result['task_rows_analyzed']==0
checks+=1
with patch.object(a,'read_packet',return_value=({},{})):
    result=a.analyze('memory'); assert result['status']=='NO_DIAGNOSTIC_RECEIPT' and result['task_rows_analyzed']==0
checks+=1
print(str(checks)+' in-memory archive/index/failure checks passed; no files written')
